<script setup lang="ts">
import {computed} from 'vue';import {useApp} from '../stores/app';import Icon from '../components/Icon.vue';import MuscleBody from '../components/MuscleBody.vue';import {coachAdvice,localDay,volume} from '../core/logic';
const app=useApp();const greeting=new Date().getHours()<12?'Good morning':new Date().getHours()<18?'Good afternoon':'Good evening';
const advice=computed(()=>coachAdvice(app.completed,app.data.checkins.at(-1)));const days=computed(()=>Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-((d.getDay()+6)%7)+i);return {label:d.toLocaleDateString('en',{weekday:'narrow'}),day:localDay(d),done:app.completed.some(s=>s.day===localDay(d))};}));
const percent=computed(()=>app.data.profile.calorieTarget?Math.min(100,app.totals.calories/app.data.profile.calorieTarget*100):0);
</script>
<template><section class="page-heading"><div><div class="eyebrow">A LITTLE STRONGER, EVERY DAY</div><h1>{{greeting}}, <span>{{app.data.profile.name}}.</span></h1><p>Show up for yourself. We’ll keep track of the progress.</p></div><RouterLink to="/train" class="button primary"><Icon name="Plus"/>{{app.active?'Resume workout':'Start a workout'}}</RouterLink></section>
<section v-if="!app.completed.length&&!app.active" class="getting-started card"><div><span class="eyebrow">NEW HERE?</span><h3>Your first workout, in three steps.</h3><p>No perfect plan needed. Start with movements you know.</p></div><div class="onboarding-steps"><RouterLink to="/settings"><span>1</span><div><strong>Make it yours</strong><small>Set your name and goals</small></div><Icon name="ChevronRight" :size="17"/></RouterLink><RouterLink to="/train"><span>2</span><div><strong>Learn a movement</strong><small>Compare its two positions</small></div><Icon name="ChevronRight" :size="17"/></RouterLink><RouterLink to="/train"><span>3</span><div><strong>Build & start</strong><small>Add exercises, then log sets</small></div><Icon name="ChevronRight" :size="17"/></RouterLink></div></section><div class="dashboard-grid"><section class="hero card"><div class="hero-content"><span class="pill"><span class="status-dot"></span> YOUR NEXT SESSION</span><h2>Small steps.<br><em>Stronger you.</em></h2><p>Build a session around your body,<br>your equipment, and your goals.</p><div class="hero-meta"><span><Icon name="Dumbbell" :size="16"/>Strength training</span><span><Icon name="Target" :size="16"/>{{app.data.profile.goal}}</span></div><RouterLink to="/train" class="button primary">{{app.active?'Continue session':'Build my workout'}}<Icon name="ArrowRight"/></RouterLink><small class="hero-footnote">Your pace. Your progress. No pressure.</small></div><div class="hero-visual" aria-hidden="true"><div class="orbit one"></div><div class="orbit two"></div><MuscleBody selected="Chest"/><span class="visual-coordinate">01 / HUMAN POTENTIAL</span><div class="floating-tag"><span class="status-dot"></span> BUILT AROUND YOU</div></div></section>
<section class="card nutrition-card"><div class="section-title"><h3>Daily fuel</h3><RouterLink to="/nutrition" aria-label="Open nutrition"><Icon name="ArrowUpRight"/></RouterLink></div><span class="muted">Nourish your next personal best.</span><div class="calorie-ring" :style="{'--progress':percent+'%'}"><div><Icon name="Flame"/><strong>{{Math.round(app.totals.calories).toLocaleString()}}</strong><small>{{app.data.profile.calorieTarget?'of '+app.data.profile.calorieTarget+' kcal':'kcal logged today'}}</small></div></div><div class="macro-grid"><div><i class="lime"></i><small>Protein{{app.data.profile.proteinTarget?' / '+app.data.profile.proteinTarget+'g':''}}</small><strong>{{Math.round(app.totals.protein)}}<span> g</span></strong></div><div><i class="blue"></i><small>Carbs</small><strong>{{Math.round(app.totals.carbs)}}<span> g</span></strong></div><div><i class="amber"></i><small>Fat</small><strong>{{Math.round(app.totals.fat)}}<span> g</span></strong></div></div><RouterLink to="/nutrition" class="button secondary full"><Icon name="Plus" :size="16"/>Log a meal</RouterLink></section>
<section class="stat-card card"><div class="stat-top"><span>Completed sessions</span><Icon name="Dumbbell"/></div><strong>{{app.completed.length}}<small>workouts</small></strong><span class="muted">A record of showing up.</span></section><section class="stat-card card"><div class="stat-top"><span>Current weight</span><Icon name="Weight"/></div><strong>{{app.data.profile.weight||'—'}}<small>kg</small></strong><RouterLink to="/progress" class="text-link">{{app.data.profile.targetWeight?'Goal · '+app.data.profile.targetWeight+' kg':'Log your starting point'}}<Icon name="ArrowUpRight" :size="15"/></RouterLink></section><section class="stat-card card"><div class="stat-top"><span>Recorded volume</span><Icon name="ChartNoAxesCombined"/></div><strong>{{volume(app.completed).toLocaleString()}}<small>kg × reps</small></strong><span class="muted">External load only.</span></section>
<section class="card week-card"><div class="section-title"><h3>Your training rhythm</h3><span class="muted">THIS WEEK</span></div><div class="week-days"><div v-for="d in days" :key="d.day" :class="{today:d.day===app.today}"><small>{{d.label}}</small><span :class="{done:d.done}"><Icon v-if="d.done" name="Check"/><span v-else class="day-dot"></span></span></div></div><p class="muted">Consistency includes recovery. Rest days count, too.</p></section><section class="card insight-card"><div class="section-title"><span class="eyebrow"><Icon name="Sparkles" :size="16"/> COACH’S CORNER</span><span class="tiny-badge">ON DEVICE</span></div><h3>{{advice.title}}</h3><p>{{advice.body}}</p><RouterLink to="/coach" class="text-link">Check in with your coach<Icon name="ArrowRight" :size="17"/></RouterLink></section>
</div><section class="quick-section"><div class="section-title"><h3>Make it yours</h3><span class="muted">ONE STEP AT A TIME</span></div><div class="quick-grid"><RouterLink to="/train"><span class="quick-icon"><Icon name="Target"/></span><div><strong>Explore by muscle</strong><small>Find your next movement</small></div><Icon name="ChevronRight"/></RouterLink><RouterLink to="/progress"><span class="quick-icon"><Icon name="ChartNoAxesCombined"/></span><div><strong>See your progress</strong><small>Your effort, over time</small></div><Icon name="ChevronRight"/></RouterLink><RouterLink to="/settings"><span class="quick-icon"><Icon name="Settings"/></span><div><strong>Set your direction</strong><small>Profile, goals & preferences</small></div><Icon name="ChevronRight"/></RouterLink></div></section></template>
